# Part of OmaSettings. Sourced by bin/omasettings; not run on its own.

# ----------------------------------------------------------------------- wifi

# NetworkManager is the authority here; nothing about wireless is stored or
# generated by OmaSettings. `-t` output escapes colons inside values, so every
# read unescapes rather than splitting naively.
wifi_device() {
  capture nmcli -t -f DEVICE,TYPE,STATE dev status \
    | awk -F: '$2 == "wifi" { print $1; exit }'
}

# Saved wireless profiles as `UUID<TAB>NAME`, with `nmcli -t`'s `\\` and `\:`
# escapes undone so SSIDs containing colons survive intact.
wifi_profiles() {
  capture nmcli -t -f UUID,NAME,TYPE con show \
    | awk '
      {
        n = 0
        field = ""
        delete fields
        for (i = 1; i <= length($0); i++) {
          c = substr($0, i, 1)
          if (c == "\\") { i++; field = field substr($0, i, 1); continue }
          if (c == ":") { fields[++n] = field; field = ""; continue }
          field = field c
        }
        fields[++n] = field
        if (fields[3] ~ /wireless/ && fields[1] != "" && fields[2] != "") {
          printf "%s\t%s\n", fields[1], fields[2]
        }
      }
    '
}

# Saved wireless network names. NetworkManager appends " 1", " 2" to a profile
# name when it re-creates a connection for an existing SSID, so emit both the
# profile name and its base SSID when a numbered duplicate exists.
wifi_saved() {
  local helper
  helper=$(command -v omarchy-wifi-helper 2>/dev/null || true)
  [[ -z $helper && -x ${HOME_DIR:-$HOME}/.local/bin/omarchy-wifi-helper ]] && helper="${HOME_DIR:-$HOME}/.local/bin/omarchy-wifi-helper"
  if [[ -n $helper ]]; then
    capture "$helper" list-saved
    return
  fi

  wifi_profiles \
    | awk -F'\t' '
      {
        print $2
        base = $2
        if (sub(/ [0-9]+$/, "", base) && base != "") print base
      }
    ' \
    | awk '!seen[$0]++'
}

# UUIDs of saved wireless profiles belonging to an SSID, matching either the
# exact profile name or NetworkManager's numbered duplicate suffix ("<SSID> 1").
wifi_profile_uuids() {
  local target=$1
  [[ -n $target ]] || return 0
  wifi_profiles \
    | awk -F'\t' -v s="$target" '
      $2 == s { print $1; next }
      {
        base = $2
        if (sub(/ [0-9]+$/, "", base) && base == s) print $1
      }
    '
}

# Normalize a saved wireless profile before activation so a stale interface
# binding (e.g. from a renamed adapter) or duplicate "<SSID> 1" profile does
# not block `nmcli con up` on multi-homed machines.
wifi_prepare_profile() {
  local ssid=$1 primary="" uuid
  while IFS= read -r uuid; do
    [[ -n $uuid ]] || continue
    if [[ -z $primary ]]; then
      primary=$uuid
    else
      nmcli con delete uuid "$uuid" >/dev/null 2>&1 || true
    fi
  done < <(wifi_profile_uuids "$ssid")

  [[ -n $primary ]] || return 1
  nmcli con modify uuid "$primary" \
    connection.id "$ssid" \
    connection.interface-name "" \
    802-11-wireless.mac-address "" \
    802-11-wireless.cloned-mac-address "permanent" \
    connection.autoconnect "yes" >/dev/null 2>&1 || true
  printf '%s\n' "$primary"
}

# Access points, strongest first, one row per network rather than one per
# radio: the same network seen from three access points is still one choice.
wifi_networks() {
  local saved
  saved=$(wifi_saved | jq -R -s -c 'split("\n") | map(select(length > 0))')

  capture nmcli -t -f IN-USE,SSID,SIGNAL,SECURITY dev wifi list --rescan no \
    | awk '
      {
        # Unescape "\:" so an SSID containing a colon survives the split.
        n = 0
        field = ""
        delete fields
        for (i = 1; i <= length($0); i++) {
          c = substr($0, i, 1)
          if (c == "\\") { i++; field = field substr($0, i, 1); continue }
          if (c == ":") { fields[++n] = field; field = ""; continue }
          field = field c
        }
        fields[++n] = field
        if (fields[2] == "") next
        printf "%s\t%s\t%s\t%s\n", (fields[1] == "*" ? "true" : "false"), fields[2], fields[3], fields[4]
      }
    ' \
    | jq -R -s -c --argjson saved "${saved:-[]}" 'split("\n")
      | map(select(length > 0) | split("\t") | . as $row
        | { ssid: $row[1],
            active: ($row[0] == "true"),
            signal: ($row[2] | tonumber? // 0),
            security: $row[3],
            secured: ($row[3] != "" and $row[3] != "--"),
            # Inside the pipe `.` is $saved, so the ssid is bound first —
            # otherwise index() would test $saved against itself.
            saved: (($saved | index($row[1])) != null) })
      | group_by(.ssid)
      | map(reduce .[] as $ap (.[0]; if $ap.signal > .signal then $ap + { active: (.active or $ap.active) } else . + { active: (.active or $ap.active) } end))
      | sort_by(-(if .active then 1000 else 0 end) - .signal)'
}

# Address, gateway and resolvers as the Wi-Fi device itself has them. The
# default route is not a reliable source here: with a VPN up it points at the
# tunnel, which is not the answer to "what is my address on this network".
wifi_connection() {
  local device=$1
  [[ -n $device ]] || { echo '{}'; return; }

  capture nmcli -t -f IP4.ADDRESS,IP4.GATEWAY,IP4.DNS dev show "$device" \
    | jq -R -s -c 'split("\n")
      | map(select(length > 0) | (index(":") // -1) as $at
        | select($at > 0) | { key: .[0:$at], value: .[$at + 1:] })
      | from_entries
      | { ip: ((.["IP4.ADDRESS[1]"] // "") | sub("/.*$"; "")),
          prefix: ((.["IP4.ADDRESS[1]"] // "") | capture("/(?<p>[0-9]+)$").p? // ""),
          gateway: (.["IP4.GATEWAY"] // ""),
          dns: ([.["IP4.DNS[1]"], .["IP4.DNS[2]"]] | map(select(. != null and . != ""))) }'
}

# The same band control the bar's network widget offers: pin 2.4, 5 or 6 GHz,
# or leave it automatic and let the radio choose.
wifi_band() {
  local report
  report=$(capture omarchy-network-band) || { echo '{}'; return; }
  jq -R -s -c 'split("\n")
    | map(select(length > 0) | split("\t"))
    | map({ key: .[0], value: (.[1] // "") })
    | from_entries
    | { current: (.band // ""),
        selected: (.selected // "auto"),
        available: ((.available // "") | split(" ") | map(select(length > 0))) }' <<<"$report"
}

wifi_state() {
  local enabled device networks connection band
  enabled=$(capture nmcli -t -f WIFI general status | head -n1)
  device=$(wifi_device)
  networks=$([[ $enabled == enabled ]] && wifi_networks || echo '[]')
  connection=$(wifi_connection "$device")
  band=$(wifi_band)

  jq -cn --argjson available "$(command -v nmcli >/dev/null 2>&1 && echo true || echo false)" \
    --argjson enabled "$([[ $enabled == enabled ]] && echo true || echo false)" \
    --arg device "${device:-}" \
    --argjson networks "${networks:-[]}" \
    --argjson connection "${connection:-{\}}" \
    --argjson band "${band:-{\}}" \
    '{ available: $available, enabled: $enabled, device: $device, networks: $networks,
       connection: $connection, band: $band,
       connected: (($networks[] | select(.active) | .ssid) // "") }'
}

wifi_cmd() {
  local action=${1:-} ssid=${2:-} password=${3:-}
  command -v nmcli >/dev/null 2>&1 || die "NetworkManager is not available"

  local helper
  helper=$(command -v omarchy-wifi-helper 2>/dev/null || true)
  [[ -z $helper && -x ${HOME_DIR:-$HOME}/.local/bin/omarchy-wifi-helper ]] && helper="${HOME_DIR:-$HOME}/.local/bin/omarchy-wifi-helper"

  case $action in
    list) wifi_state ;;
    rescan)
      nmcli dev wifi rescan >/dev/null 2>&1 || true
      # A scan takes a moment to land; without the pause the list that comes
      # back is the one we already had.
      sleep 2
      wifi_state ;;
    poll)
      # For the page's own refresh loop: ask for a scan and return what is
      # known right now, without waiting for it. NetworkManager rate-limits
      # rescans and answers the request with an error when one came too soon,
      # which is fine — the next poll picks up whatever that scan found.
      nmcli dev wifi rescan >/dev/null 2>&1 || true
      wifi_state ;;
    radio)
      case $ssid in
        on|off) nmcli radio wifi "$ssid" >/dev/null 2>&1 || die "could not turn Wi-Fi $ssid" ;;
        *) die "expected on or off" ;;
      esac ;;
    connect)
      [[ -n $ssid ]] || die "no network given"
      local output device uuid
      # A passphrase on our own command line is readable by every process on
      # the machine, so the window hands it over on stdin instead and says so
      # with this flag rather than passing the secret itself.
      if [[ $password == --password-stdin ]]; then
        IFS= read -r password || password=""
      fi
      if [[ -n $helper ]]; then
        if [[ -n $password ]]; then
          output=$(printf '%s\n' "$password" | timeout 45 "$helper" connect "$ssid" --password-stdin 2>&1) || die "${output#Error: }"
        else
          output=$(timeout 45 "$helper" connect "$ssid" 2>&1) || die "${output#Error: }"
        fi
      else
        device=$(wifi_device)
        if [[ -n $password ]]; then
          # Remove any stale or numbered duplicate profiles for this SSID first
          # so `nmcli --ask dev wifi connect` creates a single clean profile
          # while still reading the passphrase over stdin rather than argv.
          while IFS= read -r uuid; do
            [[ -n $uuid ]] && nmcli con delete uuid "$uuid" >/dev/null 2>&1 || true
          done < <(wifi_profile_uuids "$ssid")
          output=$(printf '%s\n' "$password" | timeout 45 nmcli --ask dev wifi connect "$ssid" ${device:+ifname "$device"} 2>&1)
          wifi_prepare_profile "$ssid" >/dev/null 2>&1 || true
        elif uuid=$(wifi_prepare_profile "$ssid"); then
          output=$(timeout 45 nmcli con up uuid "$uuid" ${device:+ifname "$device"} 2>&1)
        else
          output=$(timeout 45 nmcli dev wifi connect "$ssid" ${device:+ifname "$device"} 2>&1)
          wifi_prepare_profile "$ssid" >/dev/null 2>&1 || true
        fi
      fi
      grep -qiE '^error|failed' <<<"$output" && die "${output#Error: }"
      true ;;
    band)
      case $ssid in
        auto|2.4|5|6) omarchy-network-band "$ssid" >/dev/null 2>&1 || die "could not pin the band to $ssid" ;;
        *) die "expected auto, 2.4, 5 or 6" ;;
      esac ;;
    disconnect)
      local device
      device=$(wifi_device)
      [[ -n $device ]] || die "no Wi-Fi device"
      if [[ -n $helper ]]; then
        "$helper" disconnect "$device" >/dev/null 2>&1 || die "could not disconnect"
      else
        nmcli dev disconnect "$device" >/dev/null 2>&1 || die "could not disconnect"
      fi ;;
    forget)
      [[ -n $ssid ]] || die "no network given"
      if [[ -n $helper ]]; then
        "$helper" forget "$ssid" >/dev/null 2>&1 || die "no saved network called '$ssid'"
      else
        local uuid deleted=0
        while IFS= read -r uuid; do
          [[ -n $uuid ]] || continue
          if nmcli con delete uuid "$uuid" >/dev/null 2>&1; then
            deleted=1
          fi
        done < <(wifi_profile_uuids "$ssid")
        if (( ! deleted )); then
          nmcli con delete id "$ssid" >/dev/null 2>&1 || die "no saved network called '$ssid'"
        fi
      fi ;;
    *) die "unknown wifi action '$action'" ;;
  esac
}

